# Dashboard CSS embedded in Python so runtime does not depend on external CSS files.

DASHBOARD_CSS = '@import url(\'https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;500;600;700;800;900&display=swap\');\n\n*, html, body {\n    font-family: \'Poppins\', sans-serif !important;\n}\n\nhtml,\nbody,\n.stApp,\n[data-testid="stAppViewContainer"],\n[data-testid="stMain"] {\n    max-width: 100vw !important;\n    overflow-x: hidden !important;\n    overscroll-behavior-x: none !important;\n}\n\n.ap-sidebar-state {\n    display: none !important;\n}\n\n/* ══════════════════════════════════════════════════\n   GLOBAL BACKGROUND — Multi-orb pastel gradient\n══════════════════════════════════════════════════ */\n.stApp {\n    background:\n        radial-gradient(ellipse 55% 50% at 12% 12%, rgba(139,92,246,0.18) 0%, transparent 62%),\n        radial-gradient(ellipse 50% 55% at 88% 85%, rgba(6,182,212,0.15)  0%, transparent 62%),\n        radial-gradient(ellipse 38% 38% at 72%  5%, rgba(251,146,60,0.09) 0%, transparent 58%),\n        radial-gradient(ellipse 42% 42% at 28% 92%, rgba(59,130,246,0.11) 0%, transparent 58%),\n        linear-gradient(135deg, #e8eeff 0%, #f0e8ff 20%, #e6f4ff 48%, #e0f7f4 72%, #fef5e8 100%) !important;\n    min-height: 100vh;\n}\n\n#MainMenu, footer, header { visibility: hidden; }\n.block-container {\n    padding: 24px 34px 44px 38px !important;\n    max-width: 100% !important;\n}\n\n@media (max-width: 900px) {\n    .block-container {\n        padding: 18px 18px 34px 20px !important;\n    }\n}\n\n/* ══════════════════════════════════════════════════\n   SIDEBAR — Premium frosted glass\n══════════════════════════════════════════════════ */\n[data-testid="stSidebar"] {\n    background: rgba(255, 255, 255, 0.58) !important;\n    backdrop-filter: blur(32px) !important;\n    -webkit-backdrop-filter: blur(32px) !important;\n    border-right: 1px solid rgba(255, 255, 255, 0.88) !important;\n    min-width: 228px !important;\n    width: 228px !important;\n    max-width: 228px !important;\n    flex: 0 0 228px !important;\n    box-shadow: 4px 0 36px rgba(99, 102, 241, 0.07) !important;\n    visibility: visible !important;\n    overflow-x: hidden !important;\n    overflow-y: hidden !important;\n    overscroll-behavior: contain !important;\n    touch-action: pan-y !important;\n    transform: none !important;\n    transition: min-width 0.2s ease, max-width 0.2s ease, box-shadow 0.2s ease !important;\n}\n[data-testid="stSidebarContent"] {\n    padding: 0 !important;\n    overflow-x: hidden !important;\n    overflow-y: auto !important;\n    overscroll-behavior: contain !important;\n    touch-action: pan-y !important;\n    height: 100vh !important;\n    display: flex !important;\n    flex-direction: column !important;\n}\n[data-testid="collapsedControl"],\nbutton[data-testid="baseButton-header"],\n[data-testid="stSidebarCollapseButton"],\n[data-testid="stSidebarHeader"] {\n    display: none !important;\n    visibility: hidden !important;\n}\n[data-testid="stSidebar"][aria-expanded="false"] {\n    min-width: 228px !important;\n    transform: translateX(0) !important;\n}\n\nbody:has(.ap-sidebar-state.is-mini) [data-testid="stSidebar"],\nbody:has(.ap-sidebar-state.is-mini) [data-testid="stSidebar"][aria-expanded="false"] {\n    min-width: 78px !important;\n    width: 78px !important;\n    max-width: 78px !important;\n    flex-basis: 78px !important;\n}\n\nbody:has(.ap-sidebar-state.is-mini) [data-testid="stSidebarContent"] {\n    overflow-x: hidden !important;\n}\n\n.ap-brand {\n    padding: 22px 18px 16px;\n    border-bottom: 1px solid rgba(99, 102, 241, 0.10);\n}\n\n.ap-brand-mini {\n    padding: 18px 0 12px;\n    display: flex;\n    justify-content: center;\n}\n\n.ap-logo {\n    width: 36px;\n    height: 36px;\n    border-radius: 12px;\n    background: linear-gradient(135deg, #6366f1, #06b6d4);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    font-size: 12px;\n    font-weight: 900;\n    color: #fff;\n    box-shadow: 0 4px 14px rgba(99, 102, 241, 0.35);\n}\n\n.ap-brand-name {\n    font-size: 10.5px;\n    font-weight: 800;\n    color: #1e293b;\n    letter-spacing: 0.2px;\n    line-height: 1.3;\n    white-space: nowrap;\n}\n\n.ap-brand-sub {\n    font-size: 9px;\n    color: #94a3b8;\n    font-weight: 600;\n    letter-spacing: 1.5px;\n}\n\n.ap-toolbar-title {\n    padding: 10px 18px 5px 16px;\n    font-size: 8.5px;\n    font-weight: 800;\n    color: #94a3b8;\n    letter-spacing: 1.7px;\n}\n\n.ap-user {\n    padding: 12px 15px 10px;\n    display: flex;\n    align-items: center;\n    gap: 10px;\n}\n\n.ap-user-mini {\n    justify-content: center;\n    padding: 12px 0 10px;\n}\n\n.ap-avatar {\n    width: 33px;\n    height: 33px;\n    border-radius: 50%;\n    background: linear-gradient(135deg, #6366f1, #06b6d4);\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    color: #fff;\n    font-size: 12px;\n    font-weight: 700;\n    flex-shrink: 0;\n    box-shadow: 0 3px 10px rgba(99, 102, 241, 0.30);\n}\n\n/* ── Sidebar nav buttons ── */\n[data-testid="stSidebar"] div[data-testid="stButton"] {\n    padding: 0 10px !important;\n}\n\n[data-testid="stSidebar"] [data-testid="column"] div[data-testid="stButton"],\nbody:has(.ap-sidebar-state.is-mini) [data-testid="stSidebar"] div[data-testid="stButton"] {\n    padding: 0 !important;\n}\n\n[data-testid="stSidebar"] div[data-testid="stButton"] > button {\n    background: transparent !important;\n    color: #64748b !important;\n    border: none !important;\n    border-radius: 10px !important;\n    padding: 8px 12px !important;\n    font-size: 12.5px !important;\n    font-weight: 500 !important;\n    text-align: left !important;\n    box-shadow: none !important;\n    width: 100% !important;\n    margin: 1px 0 !important;\n    transform: none !important;\n    display: flex !important;\n    align-items: center !important;\n    justify-content: flex-start !important;\n    white-space: nowrap !important;\n    overflow: hidden !important;\n    transition: background 0.15s, color 0.15s !important;\n}\n[data-testid="stSidebar"] div[data-testid="stButton"] > button:hover {\n    background: rgba(99, 102, 241, 0.08) !important;\n    color: #4f46e5 !important;\n    transform: none !important;\n    box-shadow: none !important;\n}\n\n[data-testid="stSidebar"] [data-testid="column"] div[data-testid="stButton"] > button,\nbody:has(.ap-sidebar-state.is-mini) [data-testid="stSidebar"] div[data-testid="stButton"] > button {\n    width: 42px !important;\n    height: 42px !important;\n    min-height: 42px !important;\n    padding: 0 !important;\n    margin: 4px auto !important;\n    display: flex !important;\n    align-items: center !important;\n    justify-content: center !important;\n    border-radius: 13px !important;\n    background: rgba(255, 255, 255, 0.56) !important;\n    border: 1px solid rgba(255, 255, 255, 0.92) !important;\n    color: #4f46e5 !important;\n    font-size: 15px !important;\n    font-weight: 800 !important;\n    box-shadow: 0 3px 12px rgba(99, 102, 241, 0.08) !important;\n}\n\n[data-testid="stSidebar"] [data-testid="column"] div[data-testid="stButton"] > button:hover,\nbody:has(.ap-sidebar-state.is-mini) [data-testid="stSidebar"] div[data-testid="stButton"] > button:hover {\n    background: rgba(99, 102, 241, 0.11) !important;\n    border-color: rgba(99, 102, 241, 0.24) !important;\n}\n\nbody:has(.ap-sidebar-state.is-mini) .ap-toolbar-title,\nbody:has(.ap-sidebar-state.is-mini) .ap-brand-copy {\n    display: none !important;\n}\n\n/* ══════════════════════════════════════════════════\n   MAIN BUTTONS\n══════════════════════════════════════════════════ */\ndiv[data-testid="stButton"] > button {\n    background: linear-gradient(135deg, #6366f1 0%, #4f46e5 100%) !important;\n    color: #fff !important;\n    border: none !important;\n    border-radius: 12px !important;\n    padding: 9px 20px !important;\n    font-size: 13px !important;\n    font-weight: 600 !important;\n    box-shadow: 0 4px 16px rgba(99, 102, 241, 0.32) !important;\n    transition: all 0.2s !important;\n}\ndiv[data-testid="stButton"] > button:hover {\n    background: linear-gradient(135deg, #4f46e5 0%, #4338ca 100%) !important;\n    box-shadow: 0 6px 22px rgba(99, 102, 241, 0.45) !important;\n    transform: translateY(-1px) !important;\n}\n\n/* ══════════════════════════════════════════════════\n   SELECTBOX — Pill glass style\n══════════════════════════════════════════════════ */\n[data-testid="stSelectbox"] label {\n    color: #475569 !important;\n    font-size: 12px !important;\n    font-weight: 500 !important;\n}\n[data-testid="stSelectbox"] > div > div {\n    border-radius: 22px !important;\n    border: 1px solid rgba(255, 255, 255, 0.92) !important;\n    background: rgba(255, 255, 255, 0.68) !important;\n    backdrop-filter: blur(14px) !important;\n    color: #374151 !important;\n    font-size: 13px !important;\n    font-weight: 500 !important;\n    box-shadow: 0 2px 10px rgba(99, 102, 241, 0.07) !important;\n}\n\n/* ══════════════════════════════════════════════════\n   TEXT INPUT — Pill glass\n══════════════════════════════════════════════════ */\n.stTextInput > div > div > input {\n    background: rgba(255, 255, 255, 0.68) !important;\n    backdrop-filter: blur(14px) !important;\n    border: 1px solid rgba(255, 255, 255, 0.92) !important;\n    border-radius: 22px !important;\n    color: #1e293b !important;\n    font-size: 13px !important;\n    font-weight: 400 !important;\n    box-shadow: 0 2px 10px rgba(99, 102, 241, 0.07) !important;\n}\n.stTextInput > div > div > input:focus {\n    border-color: rgba(99, 102, 241, 0.42) !important;\n    box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.11) !important;\n}\n.stTextInput > div > div > input::placeholder {\n    color: #94a3b8 !important;\n}\n\n/* ══════════════════════════════════════════════════\n   METRIC CARDS — Glass with colored gradient value\n══════════════════════════════════════════════════ */\n[data-testid="metric-container"] {\n    background: rgba(255, 255, 255, 0.62) !important;\n    backdrop-filter: blur(22px) !important;\n    -webkit-backdrop-filter: blur(22px) !important;\n    border-radius: 16px !important;\n    padding: 15px 16px !important;\n    border: 1px solid rgba(255, 255, 255, 0.94) !important;\n    box-shadow:\n        0 6px 24px rgba(99, 102, 241, 0.08),\n        inset 0 1px 0 rgba(255, 255, 255, 1) !important;\n    transition: transform 0.2s, box-shadow 0.2s !important;\n}\n[data-testid="metric-container"]:hover {\n    transform: translateY(-2px) !important;\n    box-shadow:\n        0 12px 32px rgba(99, 102, 241, 0.14),\n        inset 0 1px 0 rgba(255, 255, 255, 1) !important;\n}\n[data-testid="metric-container"] > label,\n[data-testid="metric-container"] > div > label {\n    font-size: 9.5px !important;\n    color: #94a3b8 !important;\n    font-weight: 700 !important;\n    text-transform: uppercase !important;\n    letter-spacing: 0.6px !important;\n}\n[data-testid="stMetricValue"] {\n    font-size: 19px !important;\n    font-weight: 800 !important;\n    background: linear-gradient(135deg, #4f46e5, #0891b2) !important;\n    -webkit-background-clip: text !important;\n    -webkit-text-fill-color: transparent !important;\n    background-clip: text !important;\n}\n[data-testid="stMetricDelta"] {\n    font-size: 10.5px !important;\n    font-weight: 600 !important;\n}\n[data-testid="stMetricDelta"] svg { display: none; }\n\n/* ══════════════════════════════════════════════════\n   DATAFRAME — Glass table\n══════════════════════════════════════════════════ */\n[data-testid="stDataFrame"] {\n    border-radius: 12px !important;\n    border: 1px solid rgba(255, 255, 255, 0.82) !important;\n    background: rgba(255, 255, 255, 0.52) !important;\n    backdrop-filter: blur(14px) !important;\n    overflow: hidden !important;\n}\n[data-testid="stDataFrame"] th {\n    background: rgba(99, 102, 241, 0.06) !important;\n    color: #64748b !important;\n    font-weight: 700 !important;\n    font-size: 10px !important;\n    text-transform: uppercase !important;\n    letter-spacing: 0.5px !important;\n}\n[data-testid="stDataFrame"] td {\n    color: #334155 !important;\n    font-size: 12px !important;\n}\n\n/* ══════════════════════════════════════════════════\n   EXPANDER\n══════════════════════════════════════════════════ */\n[data-testid="stExpander"] {\n    border: 1px solid rgba(255, 255, 255, 0.82) !important;\n    border-radius: 14px !important;\n    background: rgba(255, 255, 255, 0.55) !important;\n    backdrop-filter: blur(16px) !important;\n}\n\n/* ══════════════════════════════════════════════════\n   NAD CARD — Main glass card\n══════════════════════════════════════════════════ */\n.nad-card {\n    background: rgba(255, 255, 255, 0.56);\n    backdrop-filter: blur(26px);\n    -webkit-backdrop-filter: blur(26px);\n    border-radius: 20px;\n    padding: 20px 22px;\n    border: 1px solid rgba(255, 255, 255, 0.90);\n    box-shadow:\n        0 8px 32px rgba(99, 102, 241, 0.07),\n        0 2px 8px rgba(0, 0, 0, 0.025),\n        inset 0 1px 0 rgba(255, 255, 255, 1),\n        inset 0 -1px 0 rgba(99, 102, 241, 0.025);\n    margin-bottom: 14px;\n    transition: box-shadow 0.2s, transform 0.2s;\n}\n.nad-card:hover {\n    box-shadow:\n        0 14px 42px rgba(99, 102, 241, 0.11),\n        0 2px 8px rgba(0, 0, 0, 0.03),\n        inset 0 1px 0 rgba(255, 255, 255, 1);\n    transform: translateY(-1px);\n}\n.nad-card-title {\n    font-size: 13px;\n    font-weight: 700;\n    color: #1e293b;\n    margin: 0 0 2px 0;\n}\n.nad-card-sub {\n    font-size: 11px;\n    color: #94a3b8;\n    margin: 0 0 12px 0;\n}\n\n/* ══════════════════════════════════════════════════\n   RS CARD\n══════════════════════════════════════════════════ */\n.rs-card {\n    background: rgba(255, 255, 255, 0.56);\n    backdrop-filter: blur(26px);\n    -webkit-backdrop-filter: blur(26px);\n    border-radius: 20px;\n    padding: 18px 20px;\n    border: 1px solid rgba(255, 255, 255, 0.90);\n    box-shadow:\n        0 8px 32px rgba(99, 102, 241, 0.07),\n        inset 0 1px 0 rgba(255, 255, 255, 1);\n    margin-bottom: 14px;\n}\n\n/* ══════════════════════════════════════════════════\n   AB CARD\n══════════════════════════════════════════════════ */\n.ab-card {\n    background: rgba(255, 255, 255, 0.56);\n    backdrop-filter: blur(26px);\n    -webkit-backdrop-filter: blur(26px);\n    border-radius: 20px;\n    padding: 18px 20px;\n    border: 1px solid rgba(255, 255, 255, 0.90);\n    box-shadow:\n        0 8px 32px rgba(99, 102, 241, 0.07),\n        inset 0 1px 0 rgba(255, 255, 255, 1);\n    margin-bottom: 14px;\n}\n\n/* ══════════════════════════════════════════════════\n   SIDEBAR NAV GROUP LABELS\n══════════════════════════════════════════════════ */\n.nav-group {\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    padding: 10px 18px 4px 16px;\n    font-size: 9px;\n    font-weight: 800;\n    color: #94a3b8;\n    letter-spacing: 2px;\n    text-transform: uppercase;\n}\n\n.nav-group-mini {\n    width: 34px;\n    height: 1px;\n    margin: 10px auto 6px;\n    border-radius: 999px;\n    background: rgba(99, 102, 241, 0.16);\n}\n\n/* ══════════════════════════════════════════════════\n   ACTIVE SIDEBAR NAV ITEM\n══════════════════════════════════════════════════ */\n.nav-active {\n    background: linear-gradient(135deg, rgba(99,102,241,0.13), rgba(6,182,212,0.07));\n    backdrop-filter: blur(8px);\n    border-radius: 10px;\n    padding: 8px 12px;\n    margin: 1px 10px;\n    display: flex;\n    align-items: center;\n    gap: 8px;\n    font-size: 12.5px;\n    font-weight: 700;\n    color: #4f46e5;\n    border: 1px solid rgba(99, 102, 241, 0.20);\n    box-shadow: 0 2px 12px rgba(99, 102, 241, 0.10);\n}\n\n.nav-icon {\n    width: 18px;\n    min-width: 18px;\n    text-align: center;\n}\n\nbody:has(.ap-sidebar-state.is-mini) .nav-active {\n    width: 42px;\n    height: 42px;\n    padding: 0;\n    margin: 4px auto;\n    align-items: center;\n    justify-content: center;\n    border-radius: 13px;\n}\n\nbody:has(.ap-sidebar-state.is-mini) .nav-label {\n    display: none !important;\n}\n\n/* ══════════════════════════════════════════════════\n   INSIGHT BOXES inside nad-card\n══════════════════════════════════════════════════ */\n.insight-box {\n    background: rgba(255, 255, 255, 0.68);\n    border: 1px solid rgba(255, 255, 255, 0.95);\n    border-radius: 12px;\n    padding: 11px 14px 11px 18px;\n    font-size: 12px;\n    color: #475569;\n    line-height: 1.65;\n    margin-bottom: 9px;\n    position: relative;\n    box-shadow: 0 2px 8px rgba(99, 102, 241, 0.05);\n}\n.insight-box::before {\n    content: \'\';\n    position: absolute;\n    left: 0; top: 0; bottom: 0;\n    width: 3px;\n    border-radius: 3px 0 0 3px;\n    background: linear-gradient(180deg, #6366f1, #06b6d4);\n}\n\n/* ══════════════════════════════════════════════════\n   STATUS BADGES\n══════════════════════════════════════════════════ */\n.badge-success {\n    background: rgba(16,185,129,0.12);\n    color: #059669;\n    border: 1px solid rgba(16,185,129,0.22);\n    padding: 3px 10px;\n    border-radius: 20px;\n    font-size: 11px;\n    font-weight: 700;\n}\n.badge-warning {\n    background: rgba(245,158,11,0.12);\n    color: #d97706;\n    border: 1px solid rgba(245,158,11,0.22);\n    padding: 3px 10px;\n    border-radius: 20px;\n    font-size: 11px;\n    font-weight: 700;\n}\n.badge-danger {\n    background: rgba(239,68,68,0.10);\n    color: #dc2626;\n    border: 1px solid rgba(239,68,68,0.18);\n    padding: 3px 10px;\n    border-radius: 20px;\n    font-size: 11px;\n    font-weight: 700;\n}\n\n/* ══════════════════════════════════════════════════\n   HR DIVIDER\n══════════════════════════════════════════════════ */\nhr {\n    border: none !important;\n    border-top: 1px solid rgba(99, 102, 241, 0.10) !important;\n}\n\n.nad-top-divider {\n    position: relative;\n    height: 2px;\n    margin: 18px 0 18px;\n    border-radius: 999px;\n    background: linear-gradient(\n        90deg,\n        rgba(99, 102, 241, 0.00) 0%,\n        rgba(99, 102, 241, 0.50) 14%,\n        rgba(6, 182, 212, 0.58) 48%,\n        rgba(16, 185, 129, 0.52) 78%,\n        rgba(16, 185, 129, 0.00) 100%\n    );\n    box-shadow: 0 8px 24px rgba(6, 182, 212, 0.14);\n}\n\n.nad-top-divider::after {\n    content: \'\';\n    position: absolute;\n    left: 8%;\n    right: 8%;\n    top: -1px;\n    height: 1px;\n    border-radius: inherit;\n    background: rgba(255, 255, 255, 0.72);\n}\n\n/* ══════════════════════════════════════════════════\n   SCROLLBAR\n══════════════════════════════════════════════════ */\n::-webkit-scrollbar { width: 5px; height: 5px; }\n::-webkit-scrollbar-track { background: transparent; }\n::-webkit-scrollbar-thumb {\n    background: rgba(99, 102, 241, 0.20);\n    border-radius: 10px;\n}\n::-webkit-scrollbar-thumb:hover {\n    background: rgba(99, 102, 241, 0.38);\n}\n\n/* ══════════════════════════════════════════════════\n   FILE UPLOADER — Force light style\n══════════════════════════════════════════════════ */\n[data-testid="stFileUploader"] *,\n[data-testid="stFileUploadDropzone"] * {\n    color: #1e293b !important;\n    opacity: 1 !important;\n}\n[data-testid="stFileUploader"] section {\n    border: 2px dashed rgba(99,102,241,0.28) !important;\n    border-radius: 14px !important;\n    background: rgba(255,255,255,0.62) !important;\n    backdrop-filter: blur(12px) !important;\n}\n[data-testid="stFileUploader"] section svg,\n[data-testid="stFileUploadDropzone"] svg {\n    fill: #6366f1 !important;\n    color: #6366f1 !important;\n    opacity: 1 !important;\n}\n[data-testid="stFileUploadDropzone"] small {\n    color: #94a3b8 !important;\n    opacity: 1 !important;\n}\n[data-testid="stFileUploader"] button {\n    background: rgba(255,255,255,0.85) !important;\n    color: #4f46e5 !important;\n    border: 1px solid rgba(99,102,241,0.22) !important;\n    border-radius: 10px !important;\n    font-weight: 600 !important;\n    box-shadow: 0 2px 8px rgba(99,102,241,0.08) !important;\n}\n'
